<script setup>
import { ref,watch,onBeforeUnmount,computed } from 'vue';
import { request } from '../../api/http';
import { session } from '../../lib/session';
import { downloadCsv } from '../../lib/cc';
import CCDataTable from './CCDataTable.vue';
const props=defineProps({from:String,to:String,channel:{type:String,default:'all'}});const emit=defineEmits(['open']);
const data=ref(null),busy=ref(false),error=ref(''),gap=ref(15),agent=ref(''),selected=ref(null);let generation=0,controller;
const rows=computed(()=>(data.value?.rows||[]).filter(row=>!agent.value||row.agent===agent.value));
const columns=[{key:'name',label:'Agent'},{key:'convox',label:'ConVox calls'},{key:'mobile',label:'Mobile calls'},{key:'answered',label:'Answered'},{key:'talk',label:'Talk (minutes)',value:r=>(r.talk/60).toFixed(1)},{key:'updates',label:'Lead updates'},{key:'idle_minutes',label:'Idle minutes'},{key:'updated_no_call',label:'Updated, no call'},{key:'talked_no_update',label:'Talked, no update'},{key:'appointment_without_booking',label:'Appt disposition, no appt'}];
const totals=computed(()=>rows.value.reduce((out,row)=>{for(const key of ['convox','mobile','answered','talk','updates'])out[key]=(out[key]||0)+row[key];return out;},{}));
async function load(){const token=++generation;controller?.abort();controller=new AbortController();busy.value=true;error.value='';data.value=null;selected.value=null;try{const body=await request('life_slimming.api.cc_report_activity.run',{args:{from_date:props.from,to_date:props.to,gap:gap.value,channel:props.channel},csrfToken:session.csrf_token,signal:controller.signal});if(token===generation)data.value=body.message;}catch(e){if(token===generation&&e.name!=='AbortError')error.value=e.message;}finally{if(token===generation)busy.value=false;}}
watch(()=>[props.from,props.to],load,{immediate:true});onBeforeUnmount(()=>{generation++;controller?.abort();});
function exportRows(){if(data.value&&!data.value.capped)downloadCsv('cc-call-activity.csv',columns,rows.value);}
</script>
<template><section class="cc-card"><h2>{{channel==='convox'?'ConVox disposition report':'Agent 360 · ConVox + Mobile + ERP activity'}}</h2><div class="cc-filters"><label>Agent<select v-model="agent"><option value="">All permitted agents</option><option v-for="row in data?.rows||[]" :key="row.agent" :value="row.agent">{{row.name}}</option></select></label><label>Idle gap<select v-model.number="gap" @change="load"><option v-for="n in [10,15,20,30]" :key="n" :value="n">{{n}} minutes</option></select></label><button :disabled="busy" @click="load">Refresh activity</button><button :disabled="!data||data.capped" @click="exportRows">Export activity CSV</button></div><p v-if="error" class="cc-error" role="alert">{{error}}</p><p v-for="warning in data?.warnings||[]" :key="warning" role="status">{{warning}}</p><p v-if="data?.capped" class="cc-error">Partial activity data. Narrow the date range before exporting.</p><p v-if="data&&!data.timeline_available">Timeline, idle gaps and mismatch checks require a range of seven days or less.</p><div class="cc-report-metrics"><div v-for="(value,key) in totals" :key="key"><strong>{{key==='talk'?(value/60).toFixed(1):value}}</strong><span>{{key==='talk'?'Talk minutes':key}}</span></div></div><CCDataTable :columns="columns" :rows="rows" :busy="busy"><template #actions="{row}"><button @click="selected=row">Timeline / outcomes</button></template></CCDataTable><section v-if="selected"><h3>{{selected.name}} · Call outcomes</h3><p v-if="selected.timeline_truncated" class="cc-error">Showing the first 1,000 timeline events. Narrow the range for full detail.</p><button @click="selected=null">Close details</button><p v-for="(count,outcome) in selected.dispositions" :key="outcome">{{outcome}}: {{count}}</p><div class="cc-table"><table><thead><tr><th>Time</th><th>Channel</th><th>Lead</th><th>Outcome</th><th>Talk seconds</th></tr></thead><tbody><tr v-for="(event,i) in selected.events" :key="i"><td>{{event.at}}</td><td>{{event.channel}}</td><td><button v-if="event.lead" @click="emit('open',event.lead)">{{event.lead}}</button></td><td>{{event.disposition||event.status}}</td><td>{{event.talk}}</td></tr></tbody></table></div></section></section></template>
